def magic_square_test(matrix):
    if not matrix:
        return False

    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return False

    target = sum(matrix[0])

    if any(sum(row) != target for row in matrix[1:]):
        return False

    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target:
            return False

    main_diag = sum(matrix[i][i] for i in range(n))
    anti_diag = sum(matrix[i][n - i - 1] for i in range(n))

    return main_diag == target and anti_diag == target
