def minPath(grid, k):
    if k == 1:
        return [1]

    n = len(grid)
    r = c = -1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r, c = i, j
                break
        if r != -1:
            break

    second = None
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            if second is None or grid[nr][nc] < second:
                second = grid[nr][nc]

    ans = [1, second] * (k // 2)
    if k % 2:
        ans.append(1)
    return ans
