from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        offline_until = [0] * numberOfUsers
        mentions = [0] * numberOfUsers

        # Same timestamp: process OFFLINE events before MESSAGE events.
        events.sort(key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        for typ, timestamp, payload in events:
            t = int(timestamp)

            # Bring back online any users whose offline duration has ended.
            for user in range(numberOfUsers):
                if offline_until[user] <= t:
                    offline_until[user] = 0

            if typ == "OFFLINE":
                user_id = int(payload)
                offline_until[user_id] = t + 60
                continue

            if payload == "ALL":
                for user in range(numberOfUsers):
                    mentions[user] += 1

            elif payload == "HERE":
                for user in range(numberOfUsers):
                    if offline_until[user] <= t:
                        mentions[user] += 1

            else:
                for token in payload.split():
                    user_id = int(token[2:])
                    mentions[user_id] += 1

        return mentions
