class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def substrings(x: str):
            parts = [""]
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    parts.append(x[i:j])
            return parts

        s_parts = substrings(s)
        t_parts = substrings(t)

        ans = 0

        for a in s_parts:
            for b in t_parts:
                length = len(a) + len(b)

                if length <= ans:
                    continue

                combined = a + b
                if combined == combined[::-1]:
                    ans = length

        return ans
